// Package componentcred owns the credential of an endpoint component that
// runs beside the gateway (a notifier, an auth provider): one shared secret
// per installed component, generated by the gateway when the component is
// installed, shown once (the install answer, a rotation), and deleted with
// it. Both directions sign with it (X-Bnbloc-Signature, internal/notify's
// Sign and Verify): bnbloc's deliveries to a notifier, and the component's
// own calls to the gateway (a notifier's replies, any endpoint component's
// GET /v1/component-settings).
//
// A credential is stored in platform settings under
// "component.credential/<kind>/<name>", sealed with the deployment's secret
// store key (internal/sealbox, bound to its key, so a row moved to another
// key does not open). The gateway creates, rotates and verifies; realtime
// signs notifier deliveries with it, so both load BNBLOC_SECRET_STORE_KEY.
package componentcred

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/luckylhb90/bnbloc/internal/extreg"
	"github.com/luckylhb90/bnbloc/internal/sealbox"
	"github.com/luckylhb90/bnbloc/internal/store"
)

const keyPrefix = "component.credential/"

// legacyNotifierPrefix keys a notifier's signing secret as it was stored
// before credentials were sealed: in clear, under "notify.secret/<name>".
// It is read (a notifier installed then keeps working across the upgrade)
// and removed by the first rotation or the uninstall; nothing writes it.
// Delete this once no deployment holds such a row (rotate each notifier
// once).
const legacyNotifierPrefix = "notify.secret/"

// kinds hold a credential: the endpoint components beside the gateway.
var kinds = []extreg.Kind{extreg.KindNotifier, extreg.KindAuthProvider, extreg.KindShareTarget, extreg.KindService}

// Holds reports whether a component kind has a credential.
func Holds(kind string) bool { return slices.Contains(kinds, extreg.Kind(kind)) }

// ErrOff reports a process without the secret store key: a credential is
// never stored or read in clear.
var ErrOff = errors.New("component credentials need " + sealbox.KeyEnv)

// Key is the platform settings key of a component's credential.
func Key(kind, name string) string { return keyPrefix + kind + "/" + name }

// Store reads and writes component credentials, with a short-TTL read cache
// for the delivery worker and the signed-call routes (a rotation in another
// process is seen within cacheTTL; through this store at once).
type Store struct {
	Settings store.PlatformSettingsStore
	// Box seals and opens credentials; nil reads only a legacy notifier
	// secret and writes nothing.
	Box *sealbox.Box
	Now func() time.Time

	mu    sync.Mutex
	cache map[string]cached
}

type cached struct {
	secret string
	found  bool
	at     time.Time
}

const cacheTTL = 5 * time.Second

func (s *Store) now() time.Time {
	if s.Now != nil {
		return s.Now()
	}
	return time.Now()
}

// Available reports whether credentials can be created.
func (s *Store) Available() bool { return s != nil && s.Settings != nil && s.Box != nil }

// Get returns a component's credential (found=false when none is stored).
func (s *Store) Get(ctx context.Context, kind, name string) (string, bool, error) {
	if s == nil || s.Settings == nil {
		return "", false, nil
	}
	key, now := Key(kind, name), s.now()
	s.mu.Lock()
	if c, ok := s.cache[key]; ok && now.Sub(c.at) < cacheTTL {
		s.mu.Unlock()
		return c.secret, c.found, nil
	}
	s.mu.Unlock()
	secret, found, err := s.read(ctx, kind, name)
	if err != nil {
		return "", false, err
	}
	s.mu.Lock()
	if s.cache == nil {
		s.cache = map[string]cached{}
	}
	s.cache[key] = cached{secret: secret, found: found, at: now}
	s.mu.Unlock()
	return secret, found, nil
}

func (s *Store) read(ctx context.Context, kind, name string) (string, bool, error) {
	key := Key(kind, name)
	row, ok, err := s.Settings.GetPlatformSetting(ctx, key)
	if err != nil {
		return "", false, err
	}
	if ok && row.Value != "" {
		if s.Box == nil {
			return "", false, fmt.Errorf("open %s: %w", key, ErrOff)
		}
		plain, err := s.Box.Open(row.Value, key)
		if err != nil {
			return "", false, fmt.Errorf("open %s: %w", key, err)
		}
		return string(plain), true, nil
	}
	if extreg.Kind(kind) != extreg.KindNotifier {
		return "", false, nil
	}
	legacy, ok, err := s.Settings.GetPlatformSetting(ctx, legacyNotifierPrefix+name)
	if err != nil || !ok {
		return "", false, err
	}
	return legacy.Value, legacy.Value != "", nil
}

// Ensure returns the stored credential, generating and storing one when
// none exists (created=true: the caller shows it once). Two concurrent
// installs store one: the loser reads the winner's.
func (s *Store) Ensure(ctx context.Context, kind, name, actor string) (string, bool, error) {
	if cur, ok, err := s.Get(ctx, kind, name); err != nil || ok {
		return cur, false, err
	}
	secret, row, err := s.seal(kind, name, actor)
	if err != nil {
		return "", false, err
	}
	if err := s.Settings.SwapPlatformSetting(ctx, nil, row); err != nil {
		if errors.Is(err, store.ErrPlatformSettingChanged) {
			s.forget(kind, name)
			cur, ok, err := s.Get(ctx, kind, name)
			if err == nil && !ok {
				err = fmt.Errorf("credential of %s/%s changed and vanished", kind, name)
			}
			return cur, false, err
		}
		return "", false, err
	}
	s.forget(kind, name)
	return secret, true, nil
}

// Rotate stores a freshly generated credential and returns it. A legacy
// notifier secret goes with it.
func (s *Store) Rotate(ctx context.Context, kind, name, actor string) (string, error) {
	secret, row, err := s.seal(kind, name, actor)
	if err != nil {
		return "", err
	}
	if err := s.Settings.PutPlatformSetting(ctx, row); err != nil {
		return "", err
	}
	s.forget(kind, name)
	if extreg.Kind(kind) == extreg.KindNotifier {
		if err := s.Settings.DeletePlatformSetting(ctx, legacyNotifierPrefix+name); err != nil {
			return "", err
		}
	}
	return secret, nil
}

func (s *Store) seal(kind, name, actor string) (string, store.PlatformSetting, error) {
	if !s.Available() {
		return "", store.PlatformSetting{}, ErrOff
	}
	if !Holds(kind) || strings.TrimSpace(name) == "" {
		return "", store.PlatformSetting{}, fmt.Errorf("a %s component has no credential", kind)
	}
	secret := NewSecret()
	key := Key(kind, name)
	sealed, err := s.Box.Seal([]byte(secret), key)
	if err != nil {
		return "", store.PlatformSetting{}, err
	}
	return secret, store.PlatformSetting{Key: key, Value: sealed, UpdatedAtMs: s.now().UnixMilli(), UpdatedBy: actor}, nil
}

// Delete removes a component's credential (uninstall), a legacy notifier
// secret included. It works without the key: nothing is opened.
func (s *Store) Delete(ctx context.Context, kind, name string) error {
	if err := s.Settings.DeletePlatformSetting(ctx, Key(kind, name)); err != nil {
		return err
	}
	if extreg.Kind(kind) == extreg.KindNotifier {
		if err := s.Settings.DeletePlatformSetting(ctx, legacyNotifierPrefix+name); err != nil {
			return err
		}
	}
	s.forget(kind, name)
	return nil
}

func (s *Store) forget(kind, name string) {
	s.mu.Lock()
	delete(s.cache, Key(kind, name))
	s.mu.Unlock()
}

// NewSecret generates a credential (32 random bytes).
func NewSecret() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return "whsec_" + hex.EncodeToString(b)
}
